import{_ as n,o as t,c as s,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"RH InkTank Ceph Day Sessions Matt Benjamin COHORTFS","description":"","frontmatter":{"title":"RH InkTank Ceph Day Sessions Matt Benjamin COHORTFS","date":"2014-07-25T00:00:00.000Z","updated":"2014-07-26T00:00:00.000Z","tags":["Ceph","Accelio","分布式存储","高性能I/O","XIO Messenger"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Matt_Benjamin_COHORTFS.md","filePath":"posts/2014/RH_InkTank_Ceph_Day_Sessions_Matt_Benjamin_COHORTFS.md","lastUpdated":1780459816000}'),o={name:"posts/2014/RH_InkTank_Ceph_Day_Sessions_Matt_Benjamin_COHORTFS.md"};function a(i,e,r,_,l,g){return t(),s("div",null,[...e[0]||(e[0]=[p("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写会议时间] <strong>会议地点</strong>： [请填写会议地点] <strong>参会人员</strong>： Matt Benjamin（Word and的CTO），其他与会人员 <strong>会议主题</strong>： Ceph项目进展及Accelio集成</p><p><strong>会议内容</strong>：</p><p><strong>一、项目背景</strong></p><p>Word and是一家位于密歇根州安阿伯的初创公司，专注于提升并行NFS的功能以应对新的应用工作负载。项目最初由NSF资助，后扩展至SAP存储堆栈。</p><p><strong>二、Accelio集成</strong></p><p>Accelio是一个高性能异步和可靠的消息库，支持硬件加速，旨在构建高性能RPC传输。项目与Melanox合作，将Ceph代码库与Accelio集成，以提升Ceph的性能，特别是在单位级别的高性能I/O性能。</p><p><strong>三、Accelio关键特性</strong></p><ul><li>支持RMA传输，未来将支持多种传输。</li><li>支持请求/响应协议和单向协议，支持多种交付语义。</li><li>支持零拷贝，内部消息路径几乎无锁。</li><li>优化线程/CPU并行，减少应用参与度。</li><li>支持高达三百万个应用程序，能够饱和单个端口。</li></ul><p><strong>四、XIO Messenger</strong></p><p>XIO Messenger是Accelio的适配器，用于将Ceph网络或消息传递映射到Infiniband。它旨在实现零拷贝和线程级别的并行。</p><p><strong>五、Ceph代码库重构</strong></p><p>为了更好地集成Accelio，Ceph代码库正在进行重构。目标是提取通用代码，以便所有消息传递器都可以使用。</p><p><strong>六、性能测试</strong></p><p>使用Accelio进行性能测试，结果表明其性能良好。在64k消息大小下，几乎饱和了XIO的可用带宽。</p><p><strong>七、项目状态</strong></p><p>XIO Messenger堆栈已完成，已集成到Ceph中。项目正在进行中，旨在使Ceph集群能够在XIO上运行。项目代码可在Accelio和Ceph的GitHub仓库中找到。</p><p><strong>八、后续行动计划</strong></p><ul><li>继续优化Ceph代码库。</li><li>完成Ceph集群在XIO上的测试和验证。</li><li>将XIO集成到Ceph的主要分支中。</li></ul><p><strong>九、其他事项</strong></p><p>项目团队将继续关注Ceph和Accelio的最新动态，以确保项目的顺利进行。</p><p><strong>总结</strong>：</p><p>本次会议介绍了Ceph项目进展和Accelio集成的情况。项目团队正在努力提高Ceph的性能，并使其能够支持更高效的消息传递。项目进展顺利，预计将在未来推出全新的Ceph版本。</p>",23)])])}const h=n(o,[["render",a]]);export{C as __pageData,h as default};
